 for(const [selector,multiple]of [['[data-photos]',true],['[data-audio]',false]])form.querySelector(selector).onchange=event=>{const selected=Array.from(event.target.files||[]);for(const file of multiple?selected:selected.slice(0,1))addFile(file);event.target.value='';};
 function endRecord(cancel=false){recordEpoch++;permission=false;if(cancel)chunks=[];if(recorder&&recorder.state!=='inactive')try{recorder.stop();}catch{}else{stopTracks();recording=false;update();}}
