   const form=card.querySelector('form');let saving=false;form.onsubmit=async event=>{event.preventDefault();if(saving)return;const state=event.submitter?.name||'accepted',feedback=form.querySelector('textarea').value.trim(),error=form.querySelector('[role=alert]');let readingResult=null;try{readingResult=readingReview?.value()||null;}catch(e){setUiMessage(error,workErrorMessage(e));return;}if(state==='needs_revision'&&!feedback&&!readingResult){setUiMessage(error,uiMessage('lessonUi.workExplainRevision'));return;}if(feedback.length>2000){setUiMessage(error,uiMessage('lessonUi.workCommentLength'));return;}saving=true;for(const button of form.querySelectorAll('button'))button.disabled=true;try{await invoke('review-work',{studentId:work.userId,homeworkRevision:work.homeworkRevision,expectedVersion:work.version,state,feedback,...(readingResult?{readingMarks:readingResult.marks}:{})});if(active())await refresh();}catch(e){if(active()&&card.isConnected){setUiMessage(error,workErrorMessage(e));saving=false;for(const button of form.querySelectorAll('button'))button.disabled=false;}}};list.append(card);
